#!/bin/bash
# Full clean of THIS project only (other Docker projects on the machine are left alone):
# containers, networks, volumes (database + GeoServer data), images, Docker build cache,
# and local caches / generated files. Afterwards: docker compose up -d --build && ./fast_backend/start.sh
#   ./del.sh        asks for confirmation
#   ./del.sh -y     no prompt
set -e
cd "$(dirname "$0")"
PROJECT="$(basename "$PWD")"

if [ "$1" != "-y" ]; then
    read -r -p "This deletes all database & GeoServer data for '$PROJECT'. Continue? [y/N] " answer
    [[ "$answer" =~ ^[Yy]$ ]] || { echo "Cancelled."; exit 0; }
fi

echo "🚫 Stopping & removing containers, networks, volumes and images..."
docker compose down --volumes --rmi all --remove-orphans

echo "🧺 Removing leftover volumes & images from earlier versions of this project..."
docker volume ls -q --filter "label=com.docker.compose.project=$PROJECT" | xargs -r docker volume rm
docker images -q "varanasi-carbon-*" | sort -u | xargs -r docker rmi -f

echo "🧼 Removing Docker build cache..."
docker builder prune -af

echo "🧹 Removing local caches & generated files..."
find fast_backend -name "__pycache__" -type d -prune -exec rm -rf {} +
rm -f fast_backend/alembic/versions/*.py      # regenerated by start.sh
rm -rf frontend/.next frontend/tsconfig.tsbuildinfo

echo "✅ Cleanup completed!"
